import {createRequire} from 'node:module';

import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

interface ValidationError {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params: Record<string, unknown>;
  message?: string;
}

type ValidateFunction = ((input: unknown) => boolean) & {errors?: ValidationError[] | null};
const Ajv = createRequire(import.meta.url)('ajv') as new (options: {
  strict: boolean;
  validateFormats: boolean;
  jsonPointers?: boolean;
}) => {
  compile(schema: object): ValidateFunction;
};

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

const ajvPackage = createRequire(import.meta.url)('ajv/package.json') as {version: string};
const ajvVersion = ajvPackage.version;
const ajvMajorVersion = Number(ajvVersion.split('.')[0]);

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validators = new WeakMap<object, ValidateFunction>();
  private readonly ajv = new Ajv({
    strict: false,
    validateFormats: false,
    ...(ajvMajorVersion < 8 ? {jsonPointers: true} : {}),
  });

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid input schema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for the execution contract. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const schema = tool.validator ? undefined : this.resolveDefinition(tool.definitionSource).inputSchema;
    let validator = tool.validator ?? (schema && this.validators.get(schema));
    if (!validator && schema) {
      const compiled = this.ajv.compile(schema);
      this.validators.set(schema, compiled);
      validator = compiled;
    }
    if (validator && !validator(input)) {
      const errors = validator.errors ?? [];
      const result = errors
        .map(error => {
          const instancePath = error.instancePath ?? error.dataPath ?? '';
          const property =
            error.keyword === 'required'
              ? error.params.missingProperty
              : error.keyword === 'additionalProperties'
                ? error.params.additionalProperty
                : undefined;
          const path =
            property === undefined
              ? instancePath
              : `${instancePath}/${String(property).replace(/~/g, '~0').replace(/\//g, '~1')}`;
          return `${path || '/'} ${error.message ?? 'is invalid'}`;
        })
        .join('; ');
      log.warn('tool', 'input validation failed', {name, errors: result});
      return {result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {createProvider} from './providerFactory.js';
import type {ResponseSchema, StructuredOutputParams} from '../types/ai.js';

// An arm that drops its argument stays invisible until compared against the direct factory.
const SCHEMA: ResponseSchema = {type: 'object', properties: {status: {type: 'string'}, count: {type: 'number'}}};

const structuredParams = (content: string): StructuredOutputParams<unknown> => ({
  messages: [{role: 'user', content}],
  systemPrompt: 'system',
  responseSchema: SCHEMA,
});

const configuredMock = () =>
  createProvider({type: 'mock', structuredResponses: new Map([['ping', {status: 'configured', count: 42}]])});

describe('createProvider', () => {
  it('forwards MockConfig, so a configured structured response survives the factory', async () => {
    await expect(configuredMock().generateStructured(structuredParams('ping'))).resolves.toEqual({
      status: 'configured',
      count: 42,
    });
  });

  it('falls back to schema-shaped defaults for a message the map does not name', async () => {
    await expect(configuredMock().generateStructured(structuredParams('unmapped'))).resolves.toEqual({
      status: '',
      count: 0,
    });
  });

  it('accepts a mock config carrying no map at all', async () => {
    const provider = createProvider({type: 'mock'});

    await expect(provider.generateStructured(structuredParams('ping'))).resolves.toEqual({status: '', count: 0});
  });

  it('dispatches each arm to a provider satisfying the full AIProvider interface', () => {
    const shape = (provider: unknown) => {
      const p = provider as Record<string, unknown>;
      return typeof p.sendMessage === 'function' && typeof p.generateStructured === 'function';
    };

    expect([
      shape(createProvider({type: 'mock'})),
      shape(createProvider({type: 'openai', apiKey: 'k', model: 'm'})),
      shape(createProvider({type: 'anthropic', apiKey: 'k', model: 'm'})),
      shape(createProvider({type: 'bedrock', region: 'eu-west-1', modelId: 'm', maxTokens: 16})),
      shape(createProvider({type: 'vertex', projectId: 'p', location: 'europe-west4', modelId: 'm'})),
    ]).toEqual([true, true, true, true, true]);
  });

  it('routes the mock arm to the mock, not to a neighbouring arm', async () => {
    const chunks = [];
    for await (const chunk of createProvider({type: 'mock'}).sendMessage({
      messages: [{role: 'user', content: 'hi'}],
      systemPrompt: 'system',
    })) {
      chunks.push(chunk.type);
    }

    expect(chunks[chunks.length - 1]).toBe('stop');
  });
});
import type {
  SchemaType,
  Content,
  GenerateContentRequest,
  GenerateContentResponse,
  FunctionCallPart,
  FunctionDeclarationSchema,
  Part,
} from '@google-cloud/vertexai';
import {AIError} from '../../types/ai.js';
import type {
  AIProvider,
  Message,
  MessageChunk,
  SendMessageParams,
  StructuredOutputParams,
  ResponseSchema,
  UsageMetadata,
} from '../../types/ai.js';
import {log} from '../../shared/logger.js';
import {requireOptionalPeer} from '../requireOptionalPeer.js';

export interface VertexConfig {
  type: 'vertex';
  projectId: string;
  location: string;
  modelId: string;
  maxTokens?: number;
  googleAuthOptions?: Record<string, unknown>;
}
export function createVertexProvider(config: VertexConfig): AIProvider {
  const {VertexAI} = requireOptionalPeer<typeof import('@google-cloud/vertexai')>('@google-cloud/vertexai');
  const vertexAI = new VertexAI({
    project: config.projectId,
    location: config.location,
    googleAuthOptions: config.googleAuthOptions,
  });

  const model = vertexAI.getGenerativeModel({
    model: config.modelId,
    generationConfig: {maxOutputTokens: config.maxTokens},
  });

  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      log.info('vertex', 'sending message', {
        modelId: config.modelId,
        messageCount: params.messages.length,
        hasTools: !!params.tools,
      });

      try {
        const request = buildRequest(params);
        if (params.maxTokens) {
          request.generationConfig = {maxOutputTokens: params.maxTokens};
        }

        const streamResult = await model.generateContentStream(request);

        for await (const chunk of streamResult.stream) {
          const candidate = chunk.candidates?.[0];
          if (!candidate?.content?.parts) continue;

          yield* partChunks(candidate.content.parts);

          const finishReason = candidate.finishReason;
          if (finishReason) {
            const stopReason =
              finishReason === 'STOP'
                ? 'end_turn'
                : finishReason === 'MAX_TOKENS'
                  ? 'max_tokens'
                  : finishReason.toLowerCase();
            yield {type: 'stop', stopReason, usage: extractUsage(chunk)};
          }
        }
      } catch (error) {
        log.error('vertex', 'stream error', {error: error instanceof Error ? error.message : 'Unknown'});
        throw mapVertexError(error);
      }
    },

    async generateStructured<T>(params: StructuredOutputParams<T>): Promise<T> {
      log.info('vertex', 'generating structured output', {
        modelId: config.modelId,
        messageCount: params.messages.length,
      });

      try {
        const structuredModel = vertexAI.getGenerativeModel({
          model: config.modelId,
          generationConfig: {
            maxOutputTokens: params.maxTokens ?? config.maxTokens,
            responseMimeType: 'application/json',
            responseSchema: mapResponseSchema(params.responseSchema),
          },
        });

        const request: GenerateContentRequest = {
          contents: params.messages.map(mapMessage),
          systemInstruction: {role: 'user', parts: [{text: params.systemPrompt}]},
        };

        const result = await structuredModel.generateContent(request);
        const text = extractText(result.response);

        return JSON.parse(text) as T;
      } catch (error) {
        if (error instanceof SyntaxError) {
          throw new AIError('Failed to parse structured response as JSON', 'PARSE_ERROR');
        }
        log.error('vertex', 'structured output error', {error: error instanceof Error ? error.message : 'Unknown'});
        throw mapVertexError(error);
      }
    },
  };
}

// A part can carry text and a function call at once, so it maps to 0, 1 or 2 chunks.
function* partChunks(parts: Part[]): Generator<MessageChunk> {
  for (const part of parts) {
    if ('text' in part && part.text) {
      yield {type: 'text', text: part.text};
    }

    if ('functionCall' in part) {
      const fc = (part as FunctionCallPart).functionCall;
      yield {
        type: 'tool_use',
        toolCall: {
          id: fc.name,
          name: fc.name,
          input: (fc.args ?? {}) as Record<string, unknown>,
        },
      };
    }
  }
}

function buildRequest(params: SendMessageParams): GenerateContentRequest {
  const request: GenerateContentRequest = {
    contents: params.messages.map(mapMessage),
    systemInstruction: {role: 'user', parts: [{text: params.systemPrompt}]},
  };

  if (params.tools?.length) {
    request.tools = [
      {
        functionDeclarations: params.tools.map(t => ({
          name: t.name,
          description: t.description,
          parameters: t.inputSchema as unknown as FunctionDeclarationSchema,
        })),
      },
    ];
  }

  return request;
}

function mapMessage(m: Message): Content {
  if (typeof m.content === 'string') {
    return {role: m.role === 'assistant' ? 'model' : 'user', parts: [{text: m.content}]};
  }

  const parts = m.content.map(block => {
    if (block.type === 'tool_use') {
      return {
        functionCall: {
          name: block.name,
          args: block.input,
        },
      };
    }
    return {
      functionResponse: {
        name: block.toolUseId,
        response: {result: block.content},
      },
    };
  });

  return {role: m.role === 'assistant' ? 'model' : 'user', parts};
}

function extractUsage(response: GenerateContentResponse): UsageMetadata | undefined {
  const usage = response.usageMetadata;
  if (!usage) return undefined;
  return {
    inputTokens: usage.promptTokenCount ?? 0,
    outputTokens: usage.candidatesTokenCount ?? 0,
    totalTokens: usage.totalTokenCount ?? 0,
  };
}

function mapVertexError(error: unknown): AIError {
  if (error instanceof AIError) return error;
  const message = error instanceof Error ? error.message : 'Unknown Vertex AI error';
  if (message.includes('429') || message.includes('RESOURCE_EXHAUSTED')) {
    // eslint-disable-next-line re-lint/no-flag-params -- AIError's retryable flag; see adrs/ADR-006-lint-suppressions.md
    return new AIError(message, 'RATE_LIMITED', true);
  }
  if (message.includes('401') || message.includes('403') || message.includes('PERMISSION_DENIED')) {
    return new AIError(message, 'AUTH_ERROR');
  }
  return new AIError(message, 'PROVIDER_ERROR');
}

function mapResponseSchema(schema: ResponseSchema): Record<string, unknown> {
  const mapped: Record<string, unknown> = {
    type: schema.type.toUpperCase() as SchemaType,
  };

  if (schema.description) mapped.description = schema.description;
  if (schema.enum) mapped.enum = schema.enum;

  if (schema.properties) {
    mapped.properties = Object.fromEntries(
      Object.entries(schema.properties).map(([key, value]) => [key, mapResponseSchema(value)])
    );
  }
  if (schema.required) mapped.required = schema.required;
  if (schema.items) mapped.items = mapResponseSchema(schema.items);

  return mapped;
}

function extractText(response: GenerateContentResponse): string {
  const candidate = response.candidates?.[0];
  const parts = candidate?.content?.parts;
  if (!parts) return '';
  const texts = parts.filter((p): p is {text: string} => 'text' in p && typeof p.text === 'string').map(p => p.text);
  return texts.join('');
}
